package com.profa.payment;import jakarta.persistence.*;import java.time.*;import java.util.*;@Entity @Table(name="payments")public class Payment{@Id@GeneratedValue(strategy=GenerationType.UUID)UUID id;UUID bookingId;UUID payerId;Integer amount;String currency="XOF";String provider;String method;String externalReference;String status="PENDING";Instant createdAt=Instant.now();public UUID getId(){return id;}public UUID getBookingId(){return bookingId;}public void setBookingId(UUID v){bookingId=v;}public UUID getPayerId(){return payerId;}public void setPayerId(UUID v){payerId=v;}public Integer getAmount(){return amount;}public void setAmount(Integer v){amount=v;}public String getCurrency(){return currency;}public String getProvider(){return provider;}public void setProvider(String v){provider=v;}public String getMethod(){return method;}public void setMethod(String v){method=v;}public String getExternalReference(){return externalReference;}public void setExternalReference(String v){externalReference=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public Instant getCreatedAt(){return createdAt;}}